using HomeServer.Core;

namespace HomeServer.Infrastructure;
public sealed partial class MediaStore
{
 private static bool PodcastAllowed(Account actor)=>actor.Enabled&&(actor.IsAdmin||actor.MaximumAge is null||actor.AllowUnrated);
 public IReadOnlyList<PodcastFeed> Podcasts(Account actor){if(!PodcastAllowed(actor))return[];using var db=Open();return Query(db,"SELECT id,title,description,image_url,enabled,revision,last_error FROM podcast_feeds WHERE user_id=$user AND enabled=1 ORDER BY title",r=>new PodcastFeed(r.GetString(0),r.GetString(1),r.GetString(2),Text(r,3),r.GetBoolean(4),r.GetInt32(5),Text(r,6)),("$user",actor.Id));}
 public string PodcastSecret(string id,string user){using var db=Open();return Scalar(db,"SELECT protected_url FROM podcast_feeds WHERE id=$id AND user_id=$user AND enabled=1",("$id",id),("$user",user)) as string??throw new DomainException("Podcast aboneliği bulunamadı.",404);}
 public PodcastFeed AddPodcast(string secret,Account actor)
 {if(!PodcastAllowed(actor)||!actor.IsAdmin&&!actor.CanDiscover)throw new DomainException("Podcast aboneliği için keşif ve içerik izni gerekli.",403);lock(_writeGate){if(Podcasts(actor).Count>=100)throw new DomainException("En fazla 100 podcast aboneliği eklenebilir.");using var db=Open();var id=Guid.NewGuid().ToString("N");Execute(db,"INSERT INTO podcast_feeds(id,user_id,protected_url,next_sync) VALUES($id,$user,$url,$now)",("$id",id),("$user",actor.Id),("$url",secret),("$now",Now()));return Podcasts(actor).Single(feed=>feed.Id==id);}}
 public void UpdatePodcast(string id,string user,string title,string description,string? image,(PodcastEpisode Episode,string Key,string ProtectedUrl,string UrlHash)[] episodes)
 {
  lock(_writeGate){_=PodcastSecret(id,user);using var db=Open();using var tx=db.BeginTransaction();MusicSql(db,tx,"UPDATE podcast_feeds SET title=$title,description=$description,image_url=$image,last_error=NULL,next_sync=$next WHERE id=$id AND user_id=$user",("$id",id),("$user",user),("$title",title),("$description",description),("$image",image),("$next",DateTimeOffset.UtcNow.AddHours(6).ToString("O")));
   foreach(var row in episodes)MusicSql(db,tx,"INSERT INTO podcast_episodes(id,feed_id,episode_key,title,description,published_at,duration_seconds,protected_url,url_hash,mime,size_bytes,explicit) VALUES($id,$feed,$key,$title,$description,$date,$duration,$url,$hash,$mime,$size,$explicit) ON CONFLICT(feed_id,episode_key) DO UPDATE SET title=$title,description=$description,published_at=$date,duration_seconds=$duration,protected_url=$url,url_hash=$hash,mime=$mime,size_bytes=$size,explicit=$explicit",("$id",row.Episode.Id),("$feed",id),("$key",row.Key),("$title",row.Episode.Title),("$description",row.Episode.Description),("$date",row.Episode.PublishedAt),("$duration",row.Episode.DurationSeconds),("$url",row.ProtectedUrl),("$hash",row.UrlHash),("$mime",row.Episode.Mime),("$size",row.Episode.SizeBytes),("$explicit",row.Episode.Explicit));tx.Commit();}
 }
 public void PodcastError(string id,string message){lock(_writeGate){using var db=Open();Execute(db,"UPDATE podcast_feeds SET last_error=$error,next_sync=$next WHERE id=$id",("$id",id),("$error",message),("$next",DateTimeOffset.UtcNow.AddHours(1).ToString("O")));}}
 public (string Id,string User)[] DuePodcasts(){using var db=Open();return Query(db,"SELECT id,user_id FROM podcast_feeds WHERE enabled=1 AND next_sync<=$now LIMIT 10",r=>(r.GetString(0),r.GetString(1)),("$now",Now())).ToArray();}
 public void RemovePodcast(string id,Account actor){lock(_writeGate){using var db=Open();Execute(db,"UPDATE podcast_feeds SET enabled=0,revision=revision+1 WHERE id=$id AND user_id=$user; UPDATE podcast_sessions SET status='closed' WHERE episode_id IN (SELECT id FROM podcast_episodes WHERE feed_id=$id) AND user_id=$user",("$id",id),("$user",actor.Id));}}
 private const string PodcastEpisodeSelect="SELECT e.id,e.feed_id,e.title,e.description,e.published_at,e.duration_seconds,e.mime,e.size_bytes,e.explicit,COALESCE(p.position_seconds,0) FROM podcast_episodes e JOIN podcast_feeds f ON f.id=e.feed_id LEFT JOIN podcast_progress p ON p.episode_id=e.id AND p.user_id=$user";
 private static PodcastEpisode ReadPodcast(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),Text(r,4),r.IsDBNull(5)?null:r.GetDouble(5),r.GetString(6),r.IsDBNull(7)?null:r.GetInt64(7),r.GetBoolean(8),r.GetDouble(9));
 public IReadOnlyList<PodcastEpisode> PodcastEpisodes(string feed,Account actor,int offset=0)
 {if(!PodcastAllowed(actor))throw new DomainException("Podcast profil kapsamı dışında.",403);_=PodcastSecret(feed,actor.Id);using var db=Open();return Query(db,PodcastEpisodeSelect+" WHERE e.feed_id=$feed AND f.user_id=$user AND f.enabled=1 AND ($adult=1 OR e.explicit=0) ORDER BY e.published_at DESC,e.id LIMIT 50 OFFSET $offset",ReadPodcast,("$feed",feed),("$user",actor.Id),("$adult",actor.IsAdmin||actor.MaximumAge is null or>=18),("$offset",Math.Max(0,offset)));}
 public PodcastEpisode RequirePodcastEpisode(string id,Account actor)
 {if(!PodcastAllowed(actor))throw new DomainException("Podcast profil kapsamı dışında.",403);using var db=Open();return Query(db,PodcastEpisodeSelect+" WHERE e.id=$id AND f.user_id=$user AND f.enabled=1 AND ($adult=1 OR e.explicit=0)",ReadPodcast,("$id",id),("$user",actor.Id),("$adult",actor.IsAdmin||actor.MaximumAge is null or>=18)).FirstOrDefault()??throw new DomainException("Podcast bölümü bulunamadı.",404);}
 public (string ProtectedUrl,string Hash) PodcastEpisodeUrl(string id){using var db=Open();return Query(db,"SELECT protected_url,url_hash FROM podcast_episodes WHERE id=$id",r=>(r.GetString(0),r.GetString(1)),("$id",id)).FirstOrDefault();}
 private const string PodcastSessionSelect="SELECT id,user_id,login_id,device_id,episode_id,url_hash,status,created_at,last_seen FROM podcast_sessions";
 private static PodcastSession ReadPodcastSession(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8));
 public PodcastSession? GetPodcastSession(string id){using var db=Open();return Query(db,PodcastSessionSelect+" WHERE id=$id",ReadPodcastSession,("$id",id)).FirstOrDefault();}
 public IReadOnlyList<PodcastSession> ActivePodcastSessions(){using var db=Open();return Query(db,PodcastSessionSelect+" WHERE status='active' AND last_seen>$now",ReadPodcastSession,("$now",DateTimeOffset.UtcNow.AddMinutes(-2).ToString("O")));}
 public PodcastSession StartPodcastSession(string episodeId,PlaybackActor actor)
 {lock(_writeGate){var user=RequirePlaybackActor(actor);_=RequirePodcastEpisode(episodeId,user);RequireTransientSlot(actor);var url=PodcastEpisodeUrl(episodeId);using var db=Open();var id=Guid.NewGuid().ToString("N");Execute(db,"INSERT INTO podcast_sessions(id,user_id,login_id,device_id,episode_id,url_hash,status,created_at,last_seen) VALUES($id,$user,$login,$device,$episode,$hash,'active',$now,$now); DELETE FROM podcast_sessions WHERE last_seen<$old",("$id",id),("$user",actor.UserId),("$login",actor.LoginId),("$device",actor.DeviceId),("$episode",episodeId),("$hash",url.Hash),("$now",Now()),("$old",DateTimeOffset.UtcNow.AddDays(-7).ToString("O")));return GetPodcastSession(id)!;}}
 public PodcastSession RequirePodcastSession(string id,PlaybackActor actor,bool touch=false)
 {lock(_writeGate){var session=GetPodcastSession(id)??throw new DomainException("Dinleme oturumu bulunamadı.",404);if(session.Status!="active"||session.UserId!=actor.UserId||session.LoginId!=actor.LoginId||session.DeviceId!=actor.DeviceId||DateTimeOffset.UtcNow-DateTimeOffset.Parse(session.LastSeen)>TimeSpan.FromMinutes(2))throw new DomainException("Dinleme oturumu sona erdi.",410);var user=RequirePlaybackActor(actor);_=RequirePodcastEpisode(session.EpisodeId,user);if(PodcastEpisodeUrl(session.EpisodeId).Hash!=session.UrlHash)throw new DomainException("Podcast ses kaynağı değişti.",409);if(touch){using var db=Open();Execute(db,"UPDATE podcast_sessions SET last_seen=$now WHERE id=$id",("$id",id),("$now",Now()));}return session;}}
 public void ClosePodcast(string id,Account actor){lock(_writeGate){using var db=Open();Execute(db,"UPDATE podcast_sessions SET status='closed' WHERE id=$id AND (user_id=$user OR $admin=1)",("$id",id),("$user",actor.Id),("$admin",actor.IsAdmin));}}
 public void SavePodcastProgress(string id,PodcastProgressInput input,Account actor)
 {_=RequirePodcastEpisode(id,actor);_=AppFiles.Id(input.ClientId);if(!double.IsFinite(input.PositionSeconds)||input.PositionSeconds is<0 or>86400||input.DurationSeconds is{}duration&&(!double.IsFinite(duration)||duration is<0 or>86400)||input.Sequence<1)throw new DomainException("Dinleme konumu geçersiz.");lock(_writeGate){using var db=Open();Execute(db,"INSERT INTO podcast_progress(user_id,episode_id,position_seconds,duration_seconds,client_id,sequence,updated_at) VALUES($user,$id,$position,$duration,$client,$sequence,$now) ON CONFLICT(user_id,episode_id) DO UPDATE SET position_seconds=$position,duration_seconds=$duration,client_id=$client,sequence=$sequence,updated_at=$now WHERE podcast_progress.client_id<>$client OR podcast_progress.sequence<$sequence",("$user",actor.Id),("$id",id),("$position",input.PositionSeconds),("$duration",input.DurationSeconds),("$client",input.ClientId),("$sequence",input.Sequence),("$now",Now()));}}
   public void RequireTransientSlot(PlaybackActor actor,string? replacingRadioClient=null)
 {
    var local=ActivePlaybackLeases().Where(row=>replacingRadioClient is null||row.LoginId!=actor.LoginId||row.ClientId!=replacingRadioClient).Select(row=>(row.UserId,row.DeviceId));var live=ActiveLiveSessions().Where(row=>replacingRadioClient is null||row.LoginId!=actor.LoginId||row.ClientId!=replacingRadioClient).Select(row=>(row.UserId,row.DeviceId));var pod=ActivePodcastSessions().Select(row=>(row.UserId,row.DeviceId));var radio=ActiveMusicRadioSessions().Where(row=>row.LoginId!=actor.LoginId||row.ClientId!=replacingRadioClient).Select(row=>(row.UserId,row.DeviceId));var all=local.Concat(live).Concat(pod).Concat(radio).ToArray();var server=GetPlaybackLimits();var personal=GetUserPlaybackLimits(actor.UserId);var device=GetPlaybackDevice(actor.DeviceId)!;
  if(all.Length>=server.MaximumStreams||all.Count(row=>row.UserId==actor.UserId)>=personal.MaximumStreams||all.Count(row=>row.DeviceId==actor.DeviceId)>=(device.MaximumStreams??server.MaximumStreamsPerDevice))throw new DomainException("Ortak oynatma sınırına ulaşıldı.",429);if(all.Where(row=>row.UserId==actor.UserId).Select(row=>row.DeviceId).Append(actor.DeviceId).Distinct().Count()>personal.MaximumDevices)throw new DomainException("Etkin cihaz sınırına ulaşıldı.",429);
 }
 public void CheckTransientLimits(PlaybackActor actor)
 {
   var all=ActivePlaybackLeases().Select(row=>(row.UserId,row.DeviceId)).Concat(ActiveLiveSessions().Select(row=>(row.UserId,row.DeviceId))).Concat(ActivePodcastSessions().Select(row=>(row.UserId,row.DeviceId))).Concat(ActiveMusicRadioSessions().Select(row=>(row.UserId,row.DeviceId))).ToArray();var server=GetPlaybackLimits();var personal=GetUserPlaybackLimits(actor.UserId);var device=GetPlaybackDevice(actor.DeviceId)!;
  if(personal.MaximumStreams==0||device.MaximumStreams==0||all.Length>server.MaximumStreams||all.Count(row=>row.UserId==actor.UserId)>personal.MaximumStreams||all.Count(row=>row.DeviceId==actor.DeviceId)>(device.MaximumStreams??server.MaximumStreamsPerDevice)||all.Where(row=>row.UserId==actor.UserId).Select(row=>row.DeviceId).Distinct().Count()>personal.MaximumDevices)throw new DomainException("Oynatma sınırları değişti; oturumu yeniden aç.",410);
 }
 public IReadOnlyList<PlaybackActivity> TransientPlaybackActivity(string? user,string currentDevice)
 {
   var result=new List<PlaybackActivity>();foreach(var session in ActiveMusicRadioSessions().Where(session=>user is null||session.UserId==user)){var actor=GetAccount(session.UserId);var device=GetPlaybackDevice(session.DeviceId);result.Add(new("radio-"+session.Id,session.UserId,actor?.DisplayName??"",session.DeviceId,device?.Name??"",session.StationId,session.Title,"radio","active",session.CreatedAt.ToString("O"),session.LastSeen.ToString("O"),false,0,null,null,session.DeviceId==currentDevice));}foreach(var session in ActiveLiveSessions().Where(session=>user is null||session.UserId==user)){var actor=GetAccount(session.UserId);var device=GetPlaybackDevice(session.DeviceId);result.Add(new("live-"+session.Id,session.UserId,actor?.DisplayName??"",session.DeviceId,device?.Name??"",session.ChannelId,GetLiveChannel(session.ChannelId).Name,"live",session.Status,session.CreatedAt,session.LastSeen,false,0,null,null,session.DeviceId==currentDevice));}
  foreach(var session in ActivePodcastSessions().Where(session=>user is null||session.UserId==user)){var actor=GetAccount(session.UserId);if(actor is null)continue;PodcastEpisode episode;try{episode=RequirePodcastEpisode(session.EpisodeId,actor);}catch(DomainException){continue;}var device=GetPlaybackDevice(session.DeviceId);result.Add(new("podcast-"+session.Id,session.UserId,actor.DisplayName,session.DeviceId,device?.Name??"",episode.Id,episode.Title,"podcast","active",session.CreatedAt,session.LastSeen,false,episode.PositionSeconds,null,null,session.DeviceId==currentDevice));}return result;
 }
}
